css:
.loader { display: inline-flex; align-items: center; gap: calc(var(--loader-size) * .07); width: var(--loader-size); padding: calc(var(--loader-size) * .07) calc(var(--loader-size) * .1); border-radius: 9999px; background: var(--loader-color); box-sizing: border-box; }
.loader .spinner { flex: none; width: calc(var(--loader-size) * .14); height: calc(var(--loader-size) * .14); border-radius: 9999px; border: calc(var(--loader-size) * .028) solid rgba(255, 255, 255, .35); border-top-color: #ffffff; animation: twSpin var(--loader-speed) linear infinite; }
.loader .label { flex: 1; height: calc(var(--loader-size) * .08); border-radius: 9999px; background: rgba(255, 255, 255, .7); }
@keyframes twSpin { to { transform: rotate(360deg); } }
